// Package server wires the services/api HTTP surface (ADR-0043). Routing +
// ServerInterface are generated by oapi-codegen (gen.go, `task codegen`, config
// oapi-codegen.api.yaml); this file implements that interface. Bodies use the
// internal/resource domain types (the store carries created_at/updated_at not on
// the wire); the generated body models are not used — same rationale as
// audit-service (see oapi-codegen.api.yaml).
package server

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"

	"github.com/go-chi/chi/v5"

	mw "aireos.local/packages/go/middleware"
	"aireos.local/services/api/internal/resource"
	"aireos.local/services/api/internal/store"
)

// Store is the narrow slice of *store.Store the handlers need.
type Store interface {
	Create(ctx context.Context, in resource.Input) (resource.Resource, error)
	Get(ctx context.Context, id string) (resource.Resource, error)
	List(ctx context.Context, after string, limit int) ([]resource.Resource, string, error)
	Update(ctx context.Context, id string, in resource.Input) (resource.Resource, error)
	Delete(ctx context.Context, id string) error
}

type apiHandlers struct{ store Store }

// New returns the api router: the generated chi-server routes wrapped in
// RequireCapability over the human-agent (operator) and service-service edges.
func New(s Store, v mw.Verifier) http.Handler {
	return HandlerWithOptions(&apiHandlers{store: s}, ChiServerOptions{
		BaseRouter:  chi.NewRouter(),
		Middlewares: []MiddlewareFunc{MiddlewareFunc(mw.RequireCapability(v, "human-agent", "service-service"))},
	})
}

func (a *apiHandlers) decodeInput(w http.ResponseWriter, r *http.Request) (resource.Input, bool) {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields() // rejects a client-supplied id with 400
	var in resource.Input
	if err := dec.Decode(&in); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "invalid request body: "+err.Error())
		return resource.Input{}, false
	}
	if err := in.Validate(); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", err.Error())
		return resource.Input{}, false
	}
	return in, true
}

func (a *apiHandlers) CreateResource(w http.ResponseWriter, r *http.Request) {
	in, ok := a.decodeInput(w, r)
	if !ok {
		return
	}
	res, err := a.store.Create(r.Context(), in)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "create failed")
		return
	}
	writeJSON(w, http.StatusCreated, res)
}

type resourcePage struct {
	Items []resource.Resource `json:"items"`
	Page  pageMeta            `json:"page"`
}

type pageMeta struct {
	NextCursor string `json:"nextCursor,omitempty"`
}

func (a *apiHandlers) ListResources(w http.ResponseWriter, r *http.Request, params ListResourcesParams) {
	limit := 50
	if params.Limit != nil {
		n := int(*params.Limit)
		if n < 1 || n > 200 {
			writeError(w, http.StatusBadRequest, "bad_request", "limit must be an integer in [1,200]")
			return
		}
		limit = n
	}
	var after string
	if params.Cursor != nil {
		after = string(*params.Cursor)
	}
	items, last, err := a.store.List(r.Context(), after, limit)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "list failed")
		return
	}
	page := resourcePage{Items: items}
	if len(items) == limit {
		page.Page.NextCursor = last
	}
	writeJSON(w, http.StatusOK, page)
}

func (a *apiHandlers) GetResource(w http.ResponseWriter, r *http.Request, id string) {
	res, err := a.store.Get(r.Context(), id)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "resource not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "get failed")
		return
	}
	writeJSON(w, http.StatusOK, res)
}

func (a *apiHandlers) UpdateResource(w http.ResponseWriter, r *http.Request, id string) {
	in, ok := a.decodeInput(w, r)
	if !ok {
		return
	}
	res, err := a.store.Update(r.Context(), id, in)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "resource not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "update failed")
		return
	}
	writeJSON(w, http.StatusOK, res)
}

func (a *apiHandlers) DeleteResource(w http.ResponseWriter, r *http.Request, id string) {
	err := a.store.Delete(r.Context(), id)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "resource not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "delete failed")
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, map[string]string{"code": code, "message": message})
}
